-- Dialekta para MySQL 5.7+ o MariaDB 10.4+. Se puede importar desde phpMyAdmin.
SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS dialekta CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE dialekta;

CREATE TABLE IF NOT EXISTS admins (
    id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,
    name VARCHAR(120) NOT NULL,
    email VARCHAR(190) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    auth_version INT UNSIGNED NOT NULL DEFAULT 1,
    reset_hash CHAR(64) DEFAULT NULL UNIQUE,
    reset_expires DATETIME DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS modules (
    id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,
    seed_key VARCHAR(60) DEFAULT NULL UNIQUE,
    title VARCHAR(180) NOT NULL,
    description TEXT NOT NULL,
    level VARCHAR(60) NOT NULL,
    status ENUM('draft','review','published') NOT NULL DEFAULT 'draft',
    data MEDIUMTEXT NOT NULL,
    version INT UNSIGNED NOT NULL DEFAULT 1,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX modules_by_update (updated_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT INTO admins (name, email, password_hash)
VALUES ('Administración Dialekta', 'admin@dialekta.edu.mx', '$2y$10$lv8g.HWO1iWOsneS5D23OODU04YdpecxdReyh2M6gS5/RjPJDw2CK')
ON DUPLICATE KEY UPDATE email=VALUES(email);

CREATE TABLE IF NOT EXISTS media_files (
    id CHAR(64) CHARACTER SET ascii PRIMARY KEY,
    mime VARCHAR(40) NOT NULL,
    bytes INT UNSIGNED NOT NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS media_chunks (
    file_id CHAR(64) CHARACTER SET ascii NOT NULL,
    part SMALLINT UNSIGNED NOT NULL,
    payload MEDIUMBLOB NOT NULL,
    PRIMARY KEY(file_id, part),
    FOREIGN KEY(file_id) REFERENCES media_files(id) ON DELETE CASCADE
) ENGINE=InnoDB;

